      "requirement": "R10",
      "code": "def test_r10_editor_splits_args(tmp_path):
    import click
    import subprocess
    from unittest.mock import patch

    p = tmp_path / "test.txt"
    p.write_text("test")

    with patch('subprocess.Popen') as mock_popen:
        mock_popen.return_value.communicate.return_value = (b'', b'')
        click.edit(filename=str(p), editor='vim -c "set nu"')
        call_args = mock_popen.call_args
        assert call_args is not None
        args, kwargs = call_args
        assert args[0] == ['vim', '-c', 'set nu']
        assert kwargs.get('shell') is False or 'shell' not in kwargs


def test_r10_pager_splits_args():
    import click
    import subprocess
    import os
    from unittest.mock import patch

    with patch('subprocess.Popen') as mock_popen:
        mock_popen.return_value.communicate.return_value = (b'', b'')
        os.environ['PAGER'] = 'less -R'
        click.echo_via_pager(['line1', 'line2'])
        call_args = mock_popen.call_args
        assert call_args is not None
        args, kwargs = call_args
        assert isinstance(args[0], list)
        assert kwargs.get('shell') is False or 'shell' not in kwargs
